<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Search, BookOpen, UserRound, MapPin, ArrowUpRight, LayoutGrid, List, ChevronLeft, ChevronRight, CheckCircle2, CircleAlert, Clock3, Info, LoaderCircle } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import AppModal from '../components/AppModal.vue'
import { toast } from '../components/ToastStack.vue'
import { api, query, encode, meetingText, sectionStatus, type Section, type Page, type Eligibility } from '../lib/api'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'

const workspace = useWorkspace(), { loading, error, run } = useAsync()
const items = ref<Section[]>([]), total = ref(0), page = ref(0), size = 12, q = ref(''), department = ref(''), availableOnly = ref(false), mode = ref('grid')
const detail = ref<Section>(), eligibility = ref<Eligibility>(), modalOpen = ref(false), detailLoading = ref(false), detailError = ref(''), busy = ref(false)
const route = useRoute(), router = useRouter()
const linkedCourse = computed(() => typeof route.query.courseId === 'string' ? route.query.courseId : '')
watch(() => [route.query.termId, workspace.terms] as const, ([id, terms]) => {
  if (typeof id === 'string' && terms.some(t => t.id === id)) workspace.termId = id
}, { immediate: true })
function changeTerm(event: Event) {
  workspace.termId = (event.target as HTMLSelectElement).value
  if (linkedCourse.value || route.query.termId) void router.replace({query:{...route.query,termId:workspace.termId,section:undefined}})
}
const pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
async function load(reset = false) { if (reset) page.value = 0; await run(() => api<Page<Section>>('/catalog' + query({ termId: workspace.termId, courseId: linkedCourse.value || undefined, q: q.value.trim(), department: department.value.trim(), availableOnly: availableOnly.value || undefined, page: page.value, size })), result => { items.value = result.items; total.value = result.total }) }
watch([() => workspace.termId, linkedCourse], () => load(true), { immediate: true })
watch(()=>route.query.section,id=>{if(typeof id==='string'&&id)void open({id})},{immediate:true})
async function open(section: Pick<Section,'id'>) { modalOpen.value = true; detailLoading.value = true; detailError.value = ''; detail.value = undefined; eligibility.value = undefined; try { const result = await Promise.all([api<Section>('/sections/' + encode(section.id)), api<Eligibility>('/student/sections/' + encode(section.id) + '/eligibility')]); detail.value = result[0]; eligibility.value = result[1] } catch (e) { detailError.value = e instanceof Error ? e.message : '课程详情加载失败' } finally { detailLoading.value = false } }
async function enroll(waitlist = false) { if (!detail.value) return; busy.value = true; detailError.value = ''; try { await api(waitlist ? '/student/waitlist' : '/student/enrollments', { method: 'POST', body: { sectionId: detail.value.id }, idempotent: true }); toast(waitlist ? '已加入候补队列，递补结果会通过消息通知。' : '选课成功，课程已加入你的课表。'); modalOpen.value = false; await load() } catch (e) { detailError.value = e instanceof Error ? e.message : '操作失败'; try { eligibility.value = await api<Eligibility>('/student/sections/' + encode(detail.value.id) + '/eligibility') } catch { /* original error remains visible */ } } finally { busy.value = false } }
function changePage(delta: number) { page.value += delta; void load() }
</script>
<template><PageHeading eyebrow="FIND YOUR NEXT POSSIBILITY" title="选课中心" description="在每一门课程里，发现新的可能。先看清安排，再做适合自己的选择。"><select :value="workspace.termId" @change="changeTerm" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select></PageHeading><div class="notice-banner"><Info :size="16"/><span>选课前会检查先修课程、时间冲突和学分上限。名额已满的课程可以申请候补，退课后按队列顺序递补。</span></div><div v-if="linkedCourse" class="notice-banner"><BookOpen :size="16"/><span>培养方案课程 {{ linkedCourse }} · 本学期已发布教学班</span><RouterLink class="text-button" :to="{path:'/student/catalog',query:{termId:workspace.termId}}">查看全部课程</RouterLink></div><section class="card mb-20"><form class="filter-bar" @submit.prevent="load(true)"><label class="search-field"><Search :size="15"/><input v-model="q" aria-label="搜索课程或教师" placeholder="搜索课程名称、编号或教师"></label><label class="sr-only" for="department-filter">学院筛选</label><input id="department-filter" v-model="department" class="select-control" placeholder="按开课学院筛选"><label class="field-checkbox"><input v-model="availableOnly" type="checkbox" @change="load(true)">只看有余位</label><button class="button button-small" type="submit" :disabled="loading">筛选课程</button><div class="spacer"/><div class="segmented" aria-label="显示方式"><button type="button" :class="{ active: mode === 'grid' }" aria-label="卡片视图" :aria-pressed="mode === 'grid'" @click="mode = 'grid'"><LayoutGrid :size="14"/></button><button type="button" :class="{ active: mode === 'list' }" aria-label="列表视图" :aria-pressed="mode === 'list'" @click="mode = 'list'"><List :size="14"/></button></div></form><div class="card-footer"><span>共找到 {{ total }} 个教学班 <span v-if="q || department || availableOnly">· 已应用筛选</span></span><span>把学习的主动权，交还给自己。</span></div></section><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load()"/><StatePanel v-else-if="!items.length"  :title="linkedCourse && !q && !department && !availableOnly ? '本学期尚未公布该课程的教学班' : '暂时没有符合条件的课程'" :description="linkedCourse ? '可切换学期，或返回培养进度查看其他待修课程。' : '可调整关键词、学院或学期。'"/><template v-else><div v-if="mode === 'grid'" class="course-grid"><article v-for="section in items" :key="section.id" class="course-card"><div class="course-card-header"><span class="course-symbol"><BookOpen :size="20"/></span><span class="tag" :class="{ 'tag-gold': section.enrolledCount >= section.capacity || section.promotionPending }">{{ sectionStatus(section) }}</span></div><p class="course-code">{{ section.courseId }} · {{ section.id }}</p><h3>{{ section.courseTitle }}</h3><div class="course-meta"><span><UserRound :size="12"/>{{ section.teacherName }}</span><span>{{ section.credits }} 学分</span><span>{{ section.department }}</span></div><p class="course-description"><template v-if="section.meetings?.length"><span v-for="(meeting, i) in section.meetings.slice(0, 2)" :key="i" style="display:block">{{ meetingText(meeting) }}</span></template><span v-else>课程时间尚未安排</span></p><div class="course-card-bottom"><div class="course-capacity"><strong>{{ section.enrolledCount }}</strong> / {{ section.capacity }} 人<span class="progress-track"><span :style="{ width: `${section.capacity ? section.enrolledCount / section.capacity * 100 : 0}%` }"/></span></div><button class="button button-secondary" @click="open(section)">课程详情<ArrowUpRight :size="12"/></button></div></article></div><section v-else class="card"><div class="table-wrap"><table><caption class="sr-only">可选教学班</caption><thead><tr><th>课程 / 教学班</th><th>教师 / 学院</th><th>学分</th><th>时间与地点</th><th>选课人数</th><th>操作</th></tr></thead><tbody><tr v-for="section in items" :key="section.id"><td><strong>{{ section.courseTitle }}</strong><small>{{ section.id }}</small></td><td>{{ section.teacherName }}<small>{{ section.department }}</small></td><td>{{ section.credits }}</td><td><small v-for="(meeting, i) in section.meetings" :key="i">{{ meetingText(meeting) }}</small></td><td>{{ section.enrolledCount }} / {{ section.capacity }}<small>{{ sectionStatus(section) }}</small></td><td><button class="text-button" @click="open(section)">查看详情<ArrowUpRight :size="12"/></button></td></tr></tbody></table></div></section><div class="card-footer" style="border:0;padding-right:0;padding-left:0"><span>第 {{ page + 1 }} 页，共 {{ pages }} 页</span><div class="pagination"><button aria-label="上一页" :disabled="page === 0 || loading" @click="changePage(-1)"><ChevronLeft :size="14"/></button><span>{{ page + 1 }} / {{ pages }}</span><button aria-label="下一页" :disabled="page + 1 >= pages || loading" @click="changePage(1)"><ChevronRight :size="14"/></button></div></div></template><AppModal :open="modalOpen" title="课程详情" wide :busy="busy" @close="modalOpen = false"><StatePanel v-if="detailLoading" loading/><div v-if="detailError" class="error-inline" role="alert">{{ detailError }}</div><template v-if="detail"><div class="detail-heading"><span class="course-symbol"><BookOpen :size="25"/></span><div><h3>{{ detail.courseTitle }}</h3><p>{{ detail.courseId }} · {{ detail.id }} · {{ detail.termName }}</p></div></div><dl class="detail-grid"><div><dt>授课教师</dt><dd>{{ detail.teacherName }}</dd></div><div><dt>课程学分</dt><dd>{{ detail.credits }} 学分</dd></div><div><dt>开课学院</dt><dd>{{ detail.department }}</dd></div><div><dt>名额情况</dt><dd>{{ detail.enrolledCount }} / {{ detail.capacity }} 人 <span v-if="detail.waitingCount">· {{ detail.waitingCount }} 人候补</span></dd></div><div class="field-full"><dt>上课时间与地点</dt><dd v-for="(meeting, i) in detail.meetings" :key="i"><MapPin :size="12"/> {{ meetingText(meeting) }}</dd></div><div v-if="detail.prerequisites?.length" class="field-full"><dt>先修课程要求</dt><dd v-for="p in detail.prerequisites" :key="p.courseId">{{ p.courseTitle || p.courseId }}：已发布成绩不低于 {{ p.minGrade }} 分</dd></div></dl><p v-if="detail.description" class="detail-summary">{{ detail.description }}</p><div class="info-divider"/><h3>你的选课资格</h3><div v-if="eligibility" class="rule-list"><div v-if="eligibility.canEnroll" class="rule-check"><CheckCircle2 :size="16"/><span>当前满足选课条件，可以选课。提交时将再次检查名额与课程安排。</span></div><div v-for="(reason, i) in eligibility.reasons" :key="i" class="rule-check fail"><CircleAlert :size="16"/><span>{{ reason.message }}</span></div><div v-if="eligibility.canWaitlist" class="rule-check"><Clock3 :size="16"/><span>可以申请候补。系统将按入队顺序重新核查资格并递补。</span></div></div><p class="muted mt-12" style="font-size:10px">资格预检反映读取时的状态，最终结果以提交时校验为准。</p></template><template #footer><button class="button button-secondary" :disabled="busy" @click="modalOpen = false">关闭</button><button v-if="eligibility?.canWaitlist" class="button button-secondary" :disabled="busy" @click="enroll(true)"><Clock3 :size="14"/>{{ busy ? '正在提交…' : '申请候补' }}</button><button v-if="eligibility?.canEnroll" class="button" :disabled="busy" @click="enroll()"><LoaderCircle v-if="busy" class="spin" :size="14"/>{{ busy ? '正在提交…' : '确认选课' }}<CheckCircle2 v-if="!busy" :size="14"/></button></template></AppModal></template>
